{
	ll t, l, r, c;
} a[N];
struct
{
	int l, r;
	ll val1, val2;
} t[N << 2];
struct nod
{
	ll w;
	int x;
	const friend bool operator<(const nod &x, const nod &y) { return x.w > y.w; }
};
priority_queue<nod> q;

void maintain(int p)
{
	t[p].val1 = min(t[p << 1].val1, t[p << 1 | 1].val1);
	t[p].val2 = min(t[p << 1].val2, t[p << 1 | 1].val2);
}

void build(int p = 1, int l = 1, int r = m)
{
	t[p] = {l, r};
	if (l == r)
	{
		if (a[l].l == 1)
			t[p].val1 = t[p].val2 = 1e18;
		else
		{
			t[p].val1 = a[l].l + a[l].t;
			t[p].val2 = a[l].l - a[l].t;
		}
		return;
	}
	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
	maintain(p);
}

void modify(int l, int r, ll val, int x, int p = 1)
{
	if (t[p].val1 > val)
		return;
	if (t[p].l == t[p].r)
	{
		dis[t[p].l] = dis[x] + a[t[p].r].c;
		q.push({dis[t[p].l], t[p].r});
		t[p].val1 = t[p].val2 = 1e18;
		return;
	}
	int mid = (t[p].l + t[p].r) >> 1;
	if (l <= mid)
		modify(l, r, val, x, p << 1);
	if (r > mid)
		modify(l, r, val, x, p << 1 | 1);
	maintain(p);
}

void update(int l, int r, ll val, int x, int p = 1)
{
	if (t[p].val2 > val)
		return;
	if (t[p].l == t[p].r)
	{
		dis[t[p].l] = dis[x] + a[t[p].r].c;
		q.push({dis[t[p].l], t[p].r});
		t[p].val1 = t[p].val2 = 1e18;
		return;
	}
	int mid = (t[p].l + t[p].r) >> 1;
	if (l <= mid)
		update(l, r, val, x, p << 1);
	if (r > mid)
		update(l, r, val, x, p << 1 | 1);
	maintain(p);
}

void dijkstra()
{
	for (int i = 1; i <= m; ++i)
	{
		dis[i] = 1e18;
		if (a[i].l == 1)
		{
			dis[i] = a[i].c;
			q.push({dis[i], i});
