		R[i] = min(n, (L[i] = R[i - 1] + 1) + len - 1);
	for (int i = 1; i <= tot; ++i)
		check(i);
}

void modify(int l, int r)
{
	if (p[l] == p[r])
	{
		for (int i = l; i <= r; ++i)
		{
			sum[p[i]] -= a[i];
			sum[p[i]] += a[i] = sqrt(a[i]);
		}
		check(p[l]);
		return;
	}
	if (!f[p[l]])
	{
		for (int i = l; i <= R[p[l]]; ++i)
		{
			sum[p[i]] -= a[i];
			sum[p[i]] += a[i] = sqrt(a[i]);
		}
		check(p[l]);
	}
	if (!f[p[r]])
	{
