using namespace std;

using ll = long long;
using lll = __int128;

const ll N = 5e5 + 5;

int n, m, a[N];
ll sum[N], lst, x, y;
struct
{
	int l, r;
	ll tag, tim, sum, lim;
} t[N << 2];

void maintain(int p) { t[p].sum = t[p << 1].sum + t[p << 1 | 1].sum, t[p].lim = t[p << 1 | 1].lim; }

void cut(int p, ll v)
{
	t[p].tag = t[p].lim = v;
	t[p].sum = (t[p].r - t[p].l + 1) * v;
	t[p].tim = 0;
}

void grow(int p, ll v)
{
	t[p].tim += v;
	t[p].sum += (sum[t[p].r] - sum[t[p].l - 1]) * v;
	t[p].lim += a[t[p].r] * v;
}

void build(int p = 1, int l = 1, int r = n)
{
	t[p] = {l, r, -1};
	if (l == r)
		return;
	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
	maintain(p);
}

void pushdown(int p)
{
	if (t[p].tag != -1)
	{
		cut(p << 1, t[p].tag);
		cut(p << 1 | 1, t[p].tag);
		t[p].tag = -1;
	}
	if (t[p].tim)
	{
		grow(p << 1, t[p].tim);
		grow(p << 1 | 1, t[p].tim);
		t[p].tim = 0;
	}
}

int find(ll v, int p = 1)
{
	if (t[p].l == t[p].r)
		return t[p].lim < v ? n + 1 : t[p].l;
	pushdown(p);
	if (t[p << 1].lim >= v)
		return find(v, p << 1);
	else
		return find(v, p << 1 | 1);
}

ll modify(int l, int r, ll v, int p = 1)
{
	if (l > r)
		return 0;
	if (l <= t[p].l && t[p].r <= r)
	{
		ll tmp = t[p].sum;
		cut(p, v);
		return tmp - t[p].sum;
	}
	int mid = (t[p].l + t[p].r) >> 1;
	ll res = 0;
	pushdown(p);
	if (l <= mid)
		res += modify(l, r, v, p << 1);
	if (r > mid)
		res += modify(l, r, v, p << 1 | 1);
	maintain(p);
	return res;
}

