	for (int k = 0; k < m; ++k)
	{
		dp[1][k] = min(k, m - k);
	}

	for (int i = 2; i <= n; ++i)
	{
		int cnt = 0;

		for (int d = 0; d < m; ++d)
		{
			bool ok = true;
			for (int j = 1; j <= m; ++j)
			{
				int j_curr = (j - 1 + d) % m + 1;
				if (a[i - 1][j] > a[i][j_curr])
				{
					ok = false;
					break;
				}
			}
			if (ok)
			{
				valid_d[cnt++] = d;
			}
		}

		for (int k = 0; k < m; ++k)
		{
			int best_prev = INF;
			for (int idx = 0; idx < cnt; ++idx)
			{
				int p = k + valid_d[idx];
				if (p >= m)
