}

void dfs(int u, int fa)
{
	dep[u] = dep[fa] + 1;
	dfn[u] = ++tot;
	f[u][0] = fa;
	for (int i = 1; i <= L; ++i)
		f[u][i] = f[f[u][i - 1]][i - 1];
