		dis[v] = dis[u] + e[i].w;
		dfs(v, u);
	}
}

int lca(int u, int v)
{
	if (u == v)
		return u;
	if (dep[u] < dep[v])
		swap(u, v);
	for (int i = L; i >= 0; --i)
	{
		if (dep[f[u][i]] >= dep[v])
			u = f[u][i];
	}
	if (u == v)
		return u;
	for (int i = L; i >= 0; --i)
	{
		if (f[u][i] != f[v][i])
			u = f[u][i], v = f[v][i];
	}
	return f[u][0];
}

