bool f[N];

void check(int x)
{
	for (int i = L[x]; i <= R[x]; ++i)
	{
		if (a[i] > 1)
			return;
	}
	f[x] = 1;
}

void build()
{
	len = sqrt(n);
	for (int i = 1; i <= n; ++i)
		p[i] = (i - 1) / len + 1, sum[p[i]] += a[i];
	tot = p[n];
	for (int i = 1; i <= tot; ++i)
		R[i] = min(n, (L[i] = R[i - 1] + 1) + len - 1);
	for (int i = 1; i <= tot; ++i)
		check(i);
}

void modify(int l, int r)
{
	if (p[l] == p[r])
	{
		for (int i = l; i <= r; ++i)
		{
			sum[p[i]] -= a[i];
			sum[p[i]] += a[i] = sqrt(a[i]);
		}
		check(p[l]);
		return;
	}
	if (!f[p[l]])
	{
		for (int i = l; i <= R[p[l]]; ++i)
		{
			sum[p[i]] -= a[i];
			sum[p[i]] += a[i] = sqrt(a[i]);
		}
		check(p[l]);
	}
	if (!f[p[r]])
	{
		for (int i = L[p[r]]; i <= r; ++i)
		{
			sum[p[i]] -= a[i];
			sum[p[i]] += a[i] = sqrt(a[i]);
		}
		check(p[r]);
	}
	for (int i = p[l] + 1; i < p[r]; ++i)
	{
		if (f[i])
			continue;
		for (int j = L[i]; j <= R[i]; ++j)
		{
			sum[i] -= a[j];
			sum[i] += a[j] = sqrt(a[j]);
		}
		check(i);
	}
}

ll query(int l, int r)
{
	ll res = 0;
	if (p[l] == p[r])
