	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
	maintain(p);
}

void pushdown(int p)
{
	if (t[p].tag != -1)
	{
		cut(p << 1, t[p].tag);
		cut(p << 1 | 1, t[p].tag);
		t[p].tag = -1;
