{
	t[p] = {l, r};
	if (l == r)
	{
		if (a[l].l == 1)
			t[p].val1 = t[p].val2 = 1e18;
		else
		{
			t[p].val1 = a[l].l + a[l].t;
			t[p].val2 = a[l].l - a[l].t;
		}
		return;
	}
	int mid = (l + r) >> 1;
	build(p << 1, l, mid);
	build(p << 1 | 1, mid + 1, r);
	maintain(p);
}

void modify(int l, int r, ll val, int x, int p = 1)
{
	if (t[p].val1 > val)
		return;
