#include <iostream>

using namespace std;

const int N = 305;
const int INF = 1e9;

int a[N][N];
int dp[N][N];
int valid_d[N];

int cute_feather = 0;

void solve()
{
	int n, m;
	cin >> n >> m;

	for (int i = 1; i <= n; ++i)
	{
		for (int j = 1; j <= m; ++j)
		{
			cin >> a[i][j];
		}
	}

	for (int k = 0; k < m; ++k)
	{
		dp[1][k] = min(k, m - k);
	}

	for (int i = 2; i <= n; ++i)
	{
		int cnt = 0;

		for (int d = 0; d < m; ++d)
		{
			bool ok = true;
			for (int j = 1; j <= m; ++j)
			{
				int j_curr = (j - 1 + d) % m + 1;
				if (a[i - 1][j] > a[i][j_curr])
				{
					ok = false;
					break;
				}
			}
			if (ok)
			{
				valid_d[cnt++] = d;
			}
		}

		for (int k = 0; k < m; ++k)
		{
			int best_prev = INF;
			for (int idx = 0; idx < cnt; ++idx)
			{
				int p = k + valid_d[idx];
				if (p >= m)
					p -= m;

				if (dp[i - 1][p] < best_prev)
				{
					best_prev = dp[i - 1][p];
				}
			}

			if (best_prev != INF)
			{
				dp[i][k] = best_prev + min(k, m - k);
			}
			else
			{
				dp[i][k] = INF;
			}
		}
	}

	int ans = INF;
	for (int k = 0; k < m; ++k)
	{
		if (dp[n][k] < ans)
		{
			ans = dp[n][k];
		}
	}

	if (ans == INF)
	{
		cout << -1 << "\n";
	}
	else
	{
		cout << ans << "\n";
	}
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int c, t;
	if (cin >> c >> t)
	{
		cute_feather++;
		while (t--)
		{
			solve();
		}
	}
	return 0;
}
